contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint newMinSum) public payable {
        require(address(c).balance == 0, "contract should have no ether");
        uint beforeBalance = address(c).balance;
        c.SetMinSum(newMinSum); if (__ESBMC_reverted()) return;
        assert(c.MinSum() == newMinSum && address(c).balance == beforeBalance);
    }

    receive() external payable {}
}

