pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 newMinSum) internal {
        vm.assume(address(c).balance == 0);
        uint beforeBalance = address(c).balance;
        try c.SetMinSum(newMinSum) {} catch { return; }
        assertTrue(c.MinSum() == newMinSum && address(c).balance == beforeBalance);
    }

    function testFuzz_run(uint256 newMinSum) public {
        _run(newMinSum);
    }

    receive() external payable {}
}
